"""Governed mesh bridge for this agent (generated by the Securi wizard).

Every inter-agent call from this agent crosses DshMeshBridge with the four
mandatory checks (AuthContext propagation, data minimization, injection
shield, composed FinOps budgets). LangGraph owns state topology; DSH owns
every execution boundary.

v3.48.8: real vertical handoffs — delegate_to_agent() locates the workspace
erp-mesh-registry.json, verifies BOTH GOAL.yaml contracts (allowedTargets /
allowedCallers + goalHash integrity), enforces BOLA tenant isolation, and
executes the target agent's governed entrypoint (src/logic/workflow.py run())
in-process, returning the structured trace + result.
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
import os
import sys

# resolve the kit's mesh engine regardless of install layout
for _cand in (
    os.path.join(os.path.dirname(__file__), "..", "..", "src"),
    os.path.join(os.path.dirname(__file__), "..", "..", "dm-agent-kit", "src"),
    os.path.join(os.path.dirname(__file__), "..", "..", "..", "node_modules", "dm-agent-kit", "dist", "src"),
):
    if os.path.isdir(_cand) and _cand not in sys.path:
        sys.path.insert(0, os.path.abspath(_cand))

from dm_agent_sec.mesh import AgentNode, DshMeshBridge, HandoffDenied  # noqa: E402

ROLE = "ui-coordinator"
ALLOWED_TARGETS = ['domain-agent']
AGENT_NAME = "erp-agent"


def _workspace_root(start_dir: str | None = None) -> str:
    """Walk up from `start_dir` (default: this file's dir) to the dir
    holding erp-mesh-registry.json."""
    start = start_dir or os.path.dirname(os.path.abspath(__file__))
    d = os.path.abspath(start)
    for _ in range(10):
        if os.path.exists(os.path.join(d, "erp-mesh-registry.json")):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            break
        d = parent
    return os.path.abspath(start)


def _load_registry(root_dir: str | None = None) -> dict:
    root = _workspace_root(root_dir)
    path = os.path.join(root, "erp-mesh-registry.json")
    if not os.path.exists(path):
        raise HandoffDenied("SECURI-MESH-REGISTRY", f"no erp-mesh-registry.json at {root}")
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def _goal_path(root: str, agent_name: str) -> str:
    return os.path.join(root, "agents", agent_name, "GOAL.yaml")


def _goal_hash(path: str) -> str:
    if not os.path.exists(path):
        return "0" * 64
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def _goal_field(path: str, field: str) -> list[str]:
    """Extract list items under a GOAL.yaml delegation field (no yaml dep)."""
    if not os.path.exists(path):
        return []
    items: list[str] = []
    capture = False
    with open(path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if stripped.startswith(field + ":"):
                capture = True
                inline = stripped[len(field) + 1:].strip()
                if inline.startswith("["):
                    inline = inline.strip("[]")
                    items.extend(p.strip().strip("'\"") for p in inline.split(",") if p.strip())
                    capture = False
                continue
            if capture:
                if stripped.startswith("- "):
                    items.append(stripped[2:].strip().strip("'\""))
                elif stripped and not stripped.startswith("#"):
                    break
    return [i for i in items if i]


def build_mesh() -> DshMeshBridge:
    """Register this agent inside the mesh with its GOAL.yaml contract."""
    here = os.path.dirname(os.path.abspath(__file__))
    node = AgentNode(
        name=AGENT_NAME,
        role=ROLE,
        allowed_targets=tuple(ALLOWED_TARGETS),
        accepts_external=ROLE == "ui-coordinator",
        multi_tenant=False,
    )
    return DshMeshBridge(
        [node],
        siem_path=os.path.join(here, ".dm-agent", "mesh-audit.jsonl"),
        audit_secret=os.environ.get("DM_AUDIT_SECRET", "dev-mesh-secret"))


def _govern_target_tools(agent_dir: str, pkg_name: str, logic_dir: str,
                         *, tenant_id: str) -> None:
    """v3.48.11: wrap the TARGET agent's TOOLS through a target-scoped
    DshSecurityBridge BEFORE workflow.py runs (previously the target's domain
    tools — verify_trust_and_tax, match_invoice, … — executed RAW during
    in-process mesh handoffs while only the caller's tools were governed).

    Every downstream tool call now emits its own governed tool_call audit
    event under subject=<target_agent>, and any tool not declared in the
    target's GOAL.yaml allowedTools is REMOVED from the dispatch surface.
    """
    import time
    tools_path = os.path.join(logic_dir, "tools.py")
    if not os.path.exists(tools_path):
        return
    spec = importlib.util.spec_from_file_location(pkg_name + ".tools", tools_path)
    if spec is None or spec.loader is None:
        return
    mod = importlib.util.module_from_spec(spec)
    sys.modules[pkg_name + ".tools"] = mod
    spec.loader.exec_module(mod)
    tools = getattr(mod, "TOOLS", None)
    if not isinstance(tools, dict) or not tools:
        return

    target = os.path.basename(agent_dir)
    # enforce the target's own GOAL.yaml allowedTools contract
    allowed = set(_goal_field(os.path.join(agent_dir, "GOAL.yaml"), "allowedTools"))
    if allowed:
        for tname in [t for t in tools if t not in allowed]:
            del tools[tname]

    try:
        import jwt
        from dm_agent_sec.core.auth_context import JWTVerifier
        from dm_agent_sec.core.ports import InMemoryOwnership
        from dm_agent_sec.langgraph.governor import GraphExecutionGovernor
        from dm_agent_kit.plugins.security_bridge import DshSecurityBridge
        secret = os.environ.get("SECURI_DEV_SECRET", "securi-dev-only-secret-key-32-bytes!")
        now = int(time.time())
        token = jwt.encode({"sub": target, "tenant_id": tenant_id,
                            "customer_id": "cust-dev", "roles": ["operator"],
                            "scope": "read write", "iat": now, "exp": now + 3600},
                           secret, algorithm="HS256")
        auth = JWTVerifier(secret=secret).verify(token)
        bridge = DshSecurityBridge(
            auth=auth, ownership=InMemoryOwnership(),
            governor=GraphExecutionGovernor(max_steps=15, max_tokens=100_000))
        try:  # FriendlyPoliceObserver: stdout/audit events for the target
            from dm_agent_sec.diagnostics.friendly_police import FriendlyPolice
            from dm_agent_kit.plugins.friendly_police_observer import FriendlyPoliceObserver
            FriendlyPoliceObserver(bridge, workdir=agent_dir,
                                   copilot=FriendlyPolice()).attach()
        except Exception:
            pass  # observer is best-effort; the bridge itself is the gate
        for tname, tfn in list(tools.items()):
            guarded = bridge.wrap_tool(tname, (lambda fn: lambda **kw: fn(kw))(tfn))
            tools[tname] = (lambda g: lambda payload=None, **kw:
                            g(**(payload if isinstance(payload, dict) else kw)))(guarded)
    except Exception as e:
        # fail-closed: an ungoverned target tool surface is never executed
        raise HandoffDenied("SECURI-MESH-GOVERNANCE",
                            f"{target}: target tool governance failed ({e})") from e


def _load_workflow(agent_dir: str, *, tenant_id: str = "tenant-1"):
    """Import agents/<name>/src/logic/workflow.py as a uniquely-named package
    module (v3.48.9: the coordinator's logic dir is already on sys.path — a
    bare `from tools import TOOLS` in the target's workflow would resolve to
    the CALLER's tools.py. Loading as <pkg>.workflow makes the relative
    import bind to the TARGET's own package)."""
    wf = os.path.join(agent_dir, "src", "logic", "workflow.py")
    if not os.path.exists(wf):
        return None
    agent = os.path.basename(agent_dir).replace("-", "_")
    pkg_name = f"mesh_logic_{agent}"
    logic_dir = os.path.dirname(wf)
    init = os.path.join(logic_dir, "__init__.py")
    # synthesize a package anchor
    pkg_spec = importlib.util.spec_from_file_location(
        pkg_name, init if os.path.exists(init) else wf,
        submodule_search_locations=[logic_dir])
    if pkg_spec is None or pkg_spec.loader is None:
        return None
    pkg = importlib.util.module_from_spec(pkg_spec)
    sys.modules[pkg_name] = pkg
    if os.path.exists(init):
        pkg_spec.loader.exec_module(pkg)
    # v3.48.11: govern the target's tool surface BEFORE the workflow imports it
    _govern_target_tools(agent_dir, pkg_name, logic_dir, tenant_id=tenant_id)
    spec = importlib.util.spec_from_file_location(f"{pkg_name}.workflow", wf)
    if spec is None or spec.loader is None:
        return None
    mod = importlib.util.module_from_spec(spec)
    sys.modules[f"{pkg_name}.workflow"] = mod
    spec.loader.exec_module(mod)
    return mod


def delegate_to_agent(target_agent: str, payload: dict, *,
                      task: str = "handoff", auth=None,
                      tenant_id: str = "tenant-1",
                      roles: tuple = ("operator",),
                      caller_dir: str | None = None) -> dict:
    """Execute a REAL governed vertical handoff to another agent in the mesh.

    Checks (fail-closed, in order):
      1. registry — target must be registered in erp-mesh-registry.json
      2. goalHash integrity — registry hash must match the on-disk GOAL.yaml
      3. caller contract — this agent's GOAL.yaml delegation.allowedTargets
         must name the target (or its role)
      4. target contract — target's GOAL.yaml delegation.allowedCallers must
         name this agent (or this agent's role)
      5. BOLA tenant isolation — auth.tenant_id (JWT) must match tenant_id
      6. governed hop — DshMeshBridge.handoff() (injection shield, data
         minimization, composed FinOps budgets, hash-chained SIEM audit)

    Then executes agents/<target>/src/logic/workflow.py::run(payload)
    in-process and returns {trace, envelope, result}.
    """
    here = caller_dir or os.path.dirname(os.path.abspath(__file__))
    root = _workspace_root(here)
    registry = _load_registry(root)
    agents = {a["name"]: a for a in registry.get("agents", [])}
    caller = AGENT_NAME

    if caller not in agents:
        raise HandoffDenied("SECURI-MESH-UNKNOWN", f"caller '{caller}' not in registry")
    if target_agent not in agents:
        raise HandoffDenied("SECURI-MESH-UNKNOWN", f"target '{target_agent}' not in registry")
    c_reg, t_reg = agents[caller], agents[target_agent]
    t_role = t_reg.get("role", "domain-agent")

    # --- 2. goalHash integrity -------------------------------------------
    for reg_entry in (c_reg, t_reg):
        actual = _goal_hash(_goal_path(root, reg_entry["name"]))
        recorded = reg_entry.get("goalHash", "")
        if recorded and recorded != "0" * 64 and actual != recorded:
            raise HandoffDenied(
                "SECURI-MESH-DRIFT",
                f"{reg_entry['name']}: GOAL.yaml changed since registration "
                f"(goalHash mismatch — re-run `dm-kit mesh register`)")

    # --- 3. caller contract (allowedTargets) ------------------------------
    caller_goal = _goal_path(root, caller)
    allowed = _goal_field(caller_goal, "allowedTargets") or list(ALLOWED_TARGETS)
    if allowed and target_agent not in allowed and t_role not in allowed:
        raise HandoffDenied(
            "SECURI-MESH-DELEGATION",
            f"{caller} ({ROLE}) may not delegate to {target_agent} ({t_role}) — "
            f"allowedTargets: {allowed}")

    # --- 4. target contract (allowedCallers) -------------------------------
    target_goal = _goal_path(root, target_agent)
    callers = _goal_field(target_goal, "allowedCallers")
    if callers and caller not in callers and ROLE not in callers:
        raise HandoffDenied(
            "SECURI-MESH-CALLER",
            f"{ROLE} is not in {target_agent}'s allowedCallers {callers}")

    # --- 5. BOLA tenant isolation ------------------------------------------
    auth_tenant = getattr(auth, "tenant_id", None) if auth is not None else None
    if auth_tenant and auth_tenant != tenant_id:
        raise HandoffDenied(
            "SECURI-MESH-BOLA",
            f"tenant mismatch: auth context '{auth_tenant}' != handoff '{tenant_id}'")

    # --- 6. governed hop across the DSH bridge ------------------------------
    nodes = [
        AgentNode(name=caller, role=ROLE,
                  allowed_targets=tuple(ALLOWED_TARGETS),
                  accepts_external=ROLE == "ui-coordinator",
                  multi_tenant=False),
        AgentNode(name=target_agent, role=t_role,
                  allowed_targets=tuple(t_reg.get("downstreamRoles", [])),
                  allowed_callers=tuple(callers),
                  accepts_external=False,
                  multi_tenant=False),
    ]
    bridge = DshMeshBridge(
        nodes,
        siem_path=os.path.join(here, ".dm-agent", "mesh-audit.jsonl"),
        audit_secret=os.environ.get("DM_AUDIT_SECRET", "dev-mesh-secret"))
    envelope = bridge.handoff(
        caller=caller, target=target_agent,
        payload={"task": task, **payload},
        tenant_id=tenant_id, roles=tuple(roles))

    # --- execute the target's governed entrypoint ---------------------------
    target_dir = os.path.join(root, "agents", target_agent)
    workflow = _load_workflow(target_dir, tenant_id=tenant_id)
    if workflow is None or not hasattr(workflow, "run"):
        result = {"status": "no-workflow",
                  "note": f"agents/{target_agent}/src/logic/workflow.py missing run()"}
    else:
        result = workflow.run({"task": task, **envelope.payload,
                               "tenant_id": envelope.tenant_id,
                               "trace_id": envelope.trace_id})

    trace = {
        "trace_id": envelope.trace_id,
        "caller": caller, "target": target_agent,
        "caller_role": ROLE, "target_role": t_role,
        "tenant_id": envelope.tenant_id,
        "masked": envelope.masked,
        "audit_chain_valid": bridge.verify_chain(),
    }
    return {"trace": trace, "envelope": {"payload": envelope.payload},
            "result": result}


def build_bridge(auth):
    """Local DSH security bridge for this agent's own tools (compat shim —
    v3.48.9 emitted a cloud-stub mesh_bridge.py containing ONLY this
    function, clobbering _workspace_root/_load_registry/delegate_to_agent).
    """
    from dm_agent_sec.core.ports import InMemoryOwnership
    from dm_agent_kit.plugins.security_bridge import DshSecurityBridge
    return DshSecurityBridge(auth=auth, ownership=InMemoryOwnership())


# ---- pre-wired governed handoff stubs -------------------------------------
def handoff_to_domain_agent(mesh, *, payload, tenant_id, roles=('operator',), parent_trace_id=None, **kw):
    # Governed hop to the domain-agent (4 mandatory DSH checks)
    return mesh.handoff(caller='erp-agent', target=kw.pop('target', 'domain-agent'), payload=payload, tenant_id=tenant_id, roles=roles, parent_trace_id=parent_trace_id, **kw)

